var CHAPTER_COUNT = 50;
var PART_NAMES = ["one", "two", "three", "four", "five"];

function chapterList() {
  var out = [];
  for (var i = 1; i <= CHAPTER_COUNT; i++) out.push(CHAPTERS[i]);
  return out;
}

function partRange(part) {
  return { from: (part - 1) * 10 + 1, to: Math.min(part * 10, CHAPTER_COUNT) };
}
